function tick(){if(state.sound&&!document.hidden)wheelAudio.tick()}
async function prepareEffects(){const ok=await wheelAudio.unlock();if(!ok)notify(t('soundBlocked'));return ok}
$('testSound').onclick=async()=>{if(busy)return;if(commit(()=>state.sound=true)){$('sound').checked=true;if(await prepareEffects()){wheelAudio.tick();wheelAudio.reveal(.15)}}};
function sectorIndex(pool,rot){const tau=2*Math.PI,position=((-rot%tau)+tau)%tau;const total=pool.reduce((a,o)=>a+o.chance,0);let edge=0;for(let i=pool.length-1;i>=0;i--){edge+=pool[i].chance/total*tau;if(position<edge)return i}return pool.length-1}

async function spin(){if(busy)return;const c=current();if(!c||c.reveal||!E.next(c))return;let r;if(testCharacter)r=E.roll(c);else if(!commit(()=>{r=E.roll(c)}))return;busy=true;$('spin').disabled=true;$('language').disabled=true;$('wheelResult').textContent=t('rolling');const pool=r.pool,index=pool.findIndex(o=>o.id===r.option.id),target=targetAngle(pool,index),start=rotation,end=spinEnd(start,target),duration=matchMedia('(prefers-reduced-motion: reduce)').matches?100:3400;let lastTick=sectorIndex(pool,start);if(state.sound)await prepareEffects();tick();await new Promise(resolve=>{const begin=performance.now();function frame(now){const p=Math.min(1,(now-begin)/duration);rotation=start+(end-start)*(1-Math.pow(1-p,4));draw(pool,rotation,r.color,-1,r.wheelId);const beat=sectorIndex(pool,rotation);if(beat!==lastTick){tick();lastTick=beat}if(p<1)requestAnimationFrame(frame);else resolve()}requestAnimationFrame(frame)});busy=false;$('spin').disabled=false;$('language').disabled=false;renderPlay();if(state.sound&&!document.hidden)wheelAudio.reveal()}
$('createForm').onsubmit=e=>{e.preventDefault();if(busy)return;const nm=$('characterName').value.trim(),owner=$('playerName').value.trim();if(!nm||!owner)return;const g=guest(),q=quota();if(g?.blocked){notify(t('blocked'));return}if(q.used>=q.limit){notify(t('limitReached'));return}const last=state.characters.filter(c=>c.guestId===g?.id).at(-1);const wait=last?Math.ceil(setting('cooldown')-(Date.now()-Date.parse(last.createdAt))/1000):0;if(wait>0){notify(t('cooldown')+': '+wait);return}if(commit(()=>{let gg=guest();if(!gg){gg={id:E.id(),name:owner,limit:null,blocked:false};state.guests.push(gg);state.guestId=gg.id}else gg.name=owner;const c=E.newCharacter(season(),nm,owner,gg.id);state.characters.push(c);state.currentId=c.id})){testCharacter=null;renderPlay()}};
$('spin').onclick=spin;$('next').onclick=()=>{if(busy)return;const c=current();if(!c)return;if(testCharacter)c.reveal=false;else if(!commit(()=>c.reveal=false))return;renderPlay()};$('finish').onclick=()=>{const c=current();if(testCharacter){showCard(c);testCharacter=null;renderPlay();return}commit(()=>state.currentId=null);setView('collection');showCard(c)};$('pause').onclick=()=>{commit(()=>state.currentId=null);renderPlay()};$('resume').onclick=()=>{const c=state.characters.find(x=>x.guestId===state.guestId&&!x.completedAt&&!x.deleted);if(c){commit(()=>state.currentId=c.id);renderPlay()}};$('sound').onchange=()=>{if(commit(()=>state.sound=$('sound').checked)){if(state.sound)prepareEffects();else wheelAudio.stop()}};$('poolToggle').onclick=()=>$('poolList').hidden=!$('poolList').hidden;
function showCard(c){$('dialogTitle').textContent=c.name;$('dialogBody').innerHTML=`<p class="small muted">${esc(c.owner)} · ${esc(name(c.season))} · ${t('revision')} ${c.season.revision}</p>${traits(c)}<div class="toolbar"><button id="cardExport">${t('exportCard')}</button></div><details><summary>${t('history')}</summary>${c.results.map(r=>`<p class="small">${esc(new Date(r.at).toLocaleString(state.lang))} · ${esc(stepLabel(r))}: ${esc(name(r.option))}</p>`).join('')}</details>`;$('cardExport').onclick=()=>download('Wheel_Lab_character.json',{schema:2,type:'characters',characters:[c]});$('dialog').showModal()}
