$('cards').onclick=e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.card)showCard(state.characters.find(c=>c.id===b.dataset.card));if(b.dataset.resume){commit(()=>state.currentId=b.dataset.resume);setView('play')}};$('search').oninput=renderCards;$('collectionSeason').onchange=renderCards;$('closeDialog').onclick=()=>$('dialog').close();
function download(filename,data,raw=false){const blob=new Blob([raw?data:JSON.stringify(data,null,2)],{type:raw&&filename.endsWith('.js')?'text/javascript':'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
